/**
 * Claude executor entrypoint — ABI-conformant.
 *
 * Reads ExecutorInput from environment variables, runs two-phase startup,
 * spawns `claude -p`, and writes ExecutorResult to result.json at RESULT_PATH.
 *
 * Formal ABI env vars (from ExecutorInput):
 *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_BASE_BRANCH
 *   EXECUTOR_WORKDIR, MGMT_REPO_URL
 *   BRIEFING_PATH, RESULT_PATH
 *   BUDGET_TOKENS (optional)
 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
 *
 * Derived paths (not passed by orchestrator — executor sets them in process.env):
 *   WORKSPACE_ROOT   = ${EXECUTOR_WORKDIR}/mgmt  (management repo clone, read-only)
 *   TASK_REPO_PATH   = ${EXECUTOR_WORKDIR}/impl  (implementation repo)
 *
 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
 *   TASK_BRANCH        — management repo feature branch for git commits
 *   GIT_AUTHOR_EMAIL   — for commit identity
 *   GIT_AUTHOR_NAME    — for commit identity
 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
 *   MAX_TURNS          — max claude CLI turns (default: 200)
 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
 *   GITNEXUS_MCP_URL   — optional GitNexus code-graph MCP server URL
 *   CLAUDE_AGENT_RUNTIME — injected as "1" for agent detection
 */

import { spawn, execSync } from "node:child_process";
import {
  mkdirSync,
  appendFileSync,
  readFileSync,
  writeFileSync,
  existsSync,
  readdirSync,
  rmSync,
  copyFileSync,
  lstatSync,
} from "node:fs";
import { join, dirname } from "node:path";
import { homedir } from "node:os";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { ExecutorResult } from "@workflow/runtime-abi";
import { isValidResult } from "@workflow/runtime-abi";
import { extractTokenUsage } from "./token-usage.js";
import { extractRagQueries } from "./rag-audit.js";
import { extractGitNexusQueries } from "./gitnexus-audit.js";
import { enforceInReviewRequiresPrUrl } from "./enforce-pr-url.js";
import { runRecovery, type SpawnResult } from "./recovery.js";
import { resolveSSHKey } from "./resolve-ssh-key.js";
import { redactSecrets } from "./redact-secrets.js";
import { buildGitEnv } from "./git-env.js";
import { flushLog } from "./flush-log.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

function requireEnv(name: string): string {
  const val = process.env[name];
  if (!val) throw new Error(`Required env var ${name} is not set`);
  return val;
}

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

/**
 * Materialize the implementation repo at taskRepoPath:
 *   - If path exists and origin matches URL: fetch + checkout + pull
 *   - Otherwise: clone fresh
 */
function materializeRepo(
  taskRepoUrl: string,
  taskRepoBranch: string,
  taskRepoPath: string,
  sshKeyPath: string | undefined,
): void {
  const env = buildGitEnv(sshKeyPath);
  const opts = { env, stdio: "pipe" as const };

  if (existsSync(join(taskRepoPath, ".git"))) {
    let originUrl = "";
    try {
      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
        ...opts, encoding: "utf-8",
      }).trim();
    } catch { /* no remote — fall through to clone */ }

    if (originUrl === taskRepoUrl) {
      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
      // Discard local changes from a previous session before checkout.
      try { execSync(`git -C "${taskRepoPath}" checkout -- .`, opts); } catch { /* ignore */ }
      try {
        execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
      } catch {
        execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
      }
      try {
        execSync(
          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
          opts,
        );
      } catch {
        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
      }
      return;
    }
  }

  // Clone fresh.
  mkdirSync(dirname(taskRepoPath), { recursive: true });
  if (existsSync(taskRepoPath)) {
    rmSync(taskRepoPath, { recursive: true, force: true });
  }
  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
  try {
    execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
  } catch {
    execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
  }
}

/**
 * Materialize the management repo at mgmtDir (read-only, always on main).
 * Idempotent: if the dir already contains a valid clone of the same URL,
 * runs fetch + checkout main + pull instead of a fresh clone.
 */
function materializeMgmtRepo(
  mgmtRepoUrl: string,
  mgmtDir: string,
  sshKeyPath: string | undefined,
): void {
  const env = buildGitEnv(sshKeyPath);
  const opts = { env, stdio: "pipe" as const };

  if (existsSync(join(mgmtDir, ".git"))) {
    let originUrl = "";
    try {
      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
        ...opts, encoding: "utf-8",
      }).trim();
    } catch { /* no remote — fall through to clone */ }

    if (originUrl === mgmtRepoUrl) {
      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
      try { execSync(`git -C "${mgmtDir}" checkout main`, opts); } catch { /* ignore */ }
      try {
        execSync(`git -C "${mgmtDir}" pull --ff-only origin main`, opts);
      } catch {
        emit({ type: "mgmt_repo_pull_diverged", mgmt_dir: mgmtDir, note: "ff-only failed — using checked-out ref" });
      }
      return;
    }
  }

  mkdirSync(dirname(mgmtDir), { recursive: true });
  if (existsSync(mgmtDir)) {
    rmSync(mgmtDir, { recursive: true, force: true });
  }
  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
}

const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
  { file: "yarn.lock",        tool: "yarn"    },
  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
  { file: "bun.lockb",        tool: "bun"     },
  { file: "go.mod",           tool: "go"      },
  { file: "requirements.txt", tool: "python3" },
  { file: "pyproject.toml",   tool: "python3" },
  { file: "Cargo.toml",       tool: "cargo"   },
];

function checkRequiredTools(taskRepoPath: string): string[] {
  const missing: string[] = [];
  const checked = new Set<string>();
  for (const { file, tool } of TOOLCHAIN_MARKERS) {
    if (checked.has(tool)) continue;
    if (!existsSync(join(taskRepoPath, file))) continue;
    checked.add(tool);
    try {
      execSync(`which ${tool}`, { stdio: "pipe" });
    } catch {
      missing.push(tool);
    }
  }
  return missing;
}

function copyWorkspaceClaude(workspaceRoot: string): void {
  const src = join(workspaceRoot, "CLAUDE.md");
  if (!existsSync(src)) return;
  const destDir = join(homedir(), ".claude");
  mkdirSync(destDir, { recursive: true });
  copyFileSync(src, join(destDir, "CLAUDE.md"));
}

function copyDirRecursive(src: string, dest: string): void {
  mkdirSync(dest, { recursive: true });
  for (const entry of readdirSync(src)) {
    const srcPath = join(src, entry);
    const destPath = join(dest, entry);
    const stat = lstatSync(srcPath);
    if (stat.isDirectory()) {
      copyDirRecursive(srcPath, destPath);
    } else if (stat.isFile()) {
      copyFileSync(srcPath, destPath);
    }
  }
}

function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
  const globalSkillsDir = join(homedir(), ".claude", "skills");
  if (existsSync(globalSkillsDir)) {
    rmSync(globalSkillsDir, { recursive: true, force: true });
  }
  mkdirSync(globalSkillsDir, { recursive: true });

  const copySkillsFrom = (sourceDir: string): void => {
    if (!existsSync(sourceDir)) return;
    let entries: string[];
    try { entries = readdirSync(sourceDir); } catch { return; }
    for (const entry of entries) {
      const srcPath = join(sourceDir, entry);
      try {
        const stat = lstatSync(srcPath);
        if (!stat.isDirectory()) continue;
        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
      } catch (e) {
        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
      }
    }
  };

  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));

  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
  if (existsSync(wsSkillsDir)) {
    let entries: string[];
    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
    for (const entry of entries) {
      if (entry === ".gitignore") continue;
      const srcPath = join(wsSkillsDir, entry);
      try {
        const stat = lstatSync(srcPath);
        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
      } catch (e) {
        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
      }
    }
  }
}

function setupGlobalSettings(workflowLocalPath: string): void {
  const src = join(workflowLocalPath, "templates", "claude-settings.json");
  const dest = join(homedir(), ".claude", "settings.json");
  if (!existsSync(src)) {
    emit({ type: "claude_settings_missing", src });
    return;
  }
  mkdirSync(dirname(dest), { recursive: true });
  copyFileSync(src, dest);
  emit({ type: "claude_settings_written", dest });
}

function writeResult(resultPath: string, result: ExecutorResult): void {
  mkdirSync(dirname(resultPath), { recursive: true });
  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  // ── Read formal ABI env vars ────────────────────────────────────────────────
  let taskId: string;
  let featureId: string;
  let taskRepoUrl: string;
  let taskRepoBranch: string;
  let executorWorkdir: string;
  let mgmtRepoUrl: string;
  let briefingPath: string;
  let resultPath: string;
  let sshKeyPath: string | undefined;
  let githubToken: string;

  try {
    taskId = requireEnv("TASK_ID");
    featureId = requireEnv("FEATURE_ID");
    taskRepoUrl = requireEnv("TASK_REPO_URL");
    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
    briefingPath = requireEnv("BRIEFING_PATH");
    resultPath = requireEnv("RESULT_PATH");
    githubToken = process.env.GITHUB_TOKEN ?? "";
    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
  } catch (e) {
    emit({ type: "executor_fatal", details: (e as Error).message });
    process.exit(1);
  }

  const budgetTokensStr = process.env.BUDGET_TOKENS;
  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;

  const implDir = join(executorWorkdir, "impl");
  const mgmtDir = join(executorWorkdir, "mgmt");

  // Day-1 single-container extras.
  const workspaceRoot = mgmtDir;
  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
  const mcpRagUrl = process.env.MCP_RAG_URL;
  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
  const gitnexusMcpUrl = process.env.GITNEXUS_MCP_URL;
  const implementationModel = process.env.IMPLEMENTATION_MODEL;
  const executorKind = (process.env.EXECUTOR_KIND ?? "impl") as "impl" | "review";
  const implPrUrl = process.env.IMPL_PR_URL ?? "";

  const runStartIso = new Date().toISOString();

  // ── 1. Two-phase repo materialization ─────────────────────────────────────
  // Phase 1: management repo (read-only — workspace rules, briefing, skills)
  try {
    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath);
    process.env.WORKSPACE_ROOT = mgmtDir;
  } catch (e) {
    const details = `mgmt repo materialization failed: ${String(e)}`;
    emit({ type: "executor_fatal", task_id: taskId, details });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Phase 2: implementation repo
  try {
    materializeRepo(taskRepoUrl, taskRepoBranch, implDir, sshKeyPath);
    process.env.TASK_REPO_PATH = implDir;
  } catch (e) {
    const details = `impl repo materialization failed: ${String(e)}`;
    emit({ type: "executor_fatal", task_id: taskId, details });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `repo_materialization_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
  const missingTools = checkRequiredTools(implDir);
  if (missingTools.length > 0) {
    const details = `missing tools: ${missingTools.join(", ")}`;
    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
    writeResult(resultPath, {
      terminal_status: "blocked",
      blocked_reason: "missing_tool",
      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
    });
    process.exit(0);
  }

  // ── 3. Workspace rules + global skills ─────────────────────────────────────
  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);

  // ── 4. Read briefing ────────────────────────────────────────────────────────
  let briefingContent: string;
  try {
    briefingContent = readFileSync(briefingPath, "utf-8");
  } catch (e) {
    emit({ type: "executor_fatal", task_id: taskId, details: `briefing read failed: ${String(e)}` });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `briefing_read_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Append hard-stop rule for missing tools.
  const effectiveBriefing =
    briefingContent +
    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;

  // ── 5. Build MCP config ─────────────────────────────────────────────────────
  const mcpArgs: string[] = [];
  if (mcpRagUrl || figmaToken || gitnexusMcpUrl) {
    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
    if (mcpRagUrl) {
      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
    }
    if (gitnexusMcpUrl) {
      mcpConfig.mcpServers["gitnexus"] = { type: "sse", url: `${gitnexusMcpUrl}/sse` };
    }
    if (figmaToken) {
      mcpConfig.mcpServers["figma"] = {
        type: "stdio",
        command: "npx",
        args: ["-y", "@figma/mcp-server"],
        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
      };
    }
    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
    mcpArgs.push("--mcp-config", mcpConfigPath);
  }

  if (mcpRagUrl) {
    emit({ type: "rag_mcp_registered", url: mcpRagUrl });
  } else {
    emit({ type: "rag_mcp_unavailable", reason: "MCP_RAG_URL not set" });
  }

  // ── 6. Spawn claude — wrapped in try/finally for Layer 1 recovery ───────────
  const claudeEnv = {
    ...buildGitEnv(sshKeyPath),
    CLAUDE_AGENT_RUNTIME: "1",
    RESULT_PATH: resultPath,
    GITHUB_TOKEN: githubToken,
  };

  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });

  let spawnResult: SpawnResult | undefined;
  let tokenUsage: { input: number; output: number; model: string; cost_usd: number; pricingFallback: boolean } | undefined;
  let logFlushed = false;

  try {
    spawnResult = await new Promise<SpawnResult>((resolve) => {
      const stdoutChunks: string[] = [];

      const child = spawn(
        "claude",
        [
          "-p", effectiveBriefing,
          "--max-turns", String(maxTurns),
          "--output-format", "stream-json",
          "--verbose",
          "--dangerously-skip-permissions",
          ...(implementationModel ? ["--model", implementationModel] : []),
          ...mcpArgs,
        ],
        { cwd: implDir, env: claudeEnv },
      );

      child.stdout.setEncoding("utf-8");
      child.stderr.setEncoding("utf-8");

      let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
      let stdoutLineBuf = "";
      child.stdout.on("data", (chunk: string) => {
        stdoutChunks.push(chunk);
        process.stdout.write(chunk);
        if (resultWatchdog === null) {
          stdoutLineBuf += chunk;
          const lines = stdoutLineBuf.split("\n");
          stdoutLineBuf = lines.pop() ?? "";
          for (const line of lines) {
            if (line.includes('"type":"result"')) {
              resultWatchdog = setTimeout(() => {
                if (!child.killed) child.kill("SIGTERM");
              }, 30_000);
              break;
            }
          }
        }
      });

      child.stderr.on("data", (chunk: string) => {
        process.stderr.write(chunk);
      });

      child.on("error", (err: Error) => {
        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
        resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
      });

      child.on("exit", () => {
        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
        setTimeout(() => {
          if (!child.stdout.destroyed) child.stdout.destroy();
          if (!child.stderr.destroyed) child.stderr.destroy();
        }, 0);
      });

      child.on("close", (code: number | null, signal: string | null) => {
        resolve({ stdout: stdoutChunks.join(""), status: code, signal });
      });
    });

    emit({
      type: "claude_exit",
      task_id: taskId,
      feature_id: featureId,
      exit_code: spawnResult.status,
      signal: spawnResult.signal ?? null,
    });

    // ── 7. Token audit ────────────────────────────────────────────────────────
    tokenUsage = spawnResult.stdout ? extractTokenUsage(spawnResult.stdout) : undefined;

    if (tokenUsage === undefined) {
      emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
    } else {
      if (tokenUsage.pricingFallback) {
        emit({ type: "pricing_fallback", task_id: taskId, model: tokenUsage.model, note: "unknown model — Sonnet rates applied" });
      }
      emit({
        type: "budget_audit",
        task_id: taskId,
        feature_id: featureId,
        total_tokens: tokenUsage.input + tokenUsage.output,
        max_tokens: budgetTokens,
      });
    }

    // ── 7a. RAG query audit
    if (spawnResult.stdout) {
      for (const rq of extractRagQueries(spawnResult.stdout)) {
        emit({ type: "rag_query", ...rq });
      }
    }

    // ── 7b. GitNexus query audit
    if (spawnResult.stdout) {
      for (const gq of extractGitNexusQueries(spawnResult.stdout)) {
        emit({ type: "gitnexus_query", ...gq });
      }
    }

    // ── 8. Check for result.json written by Claude ────────────────────────────
    // The pr_url is sourced ONLY from Claude's result.json. The executor does not
    // scrape stdout for GitHub URLs, and does not synthesize an in_review result
    // when Claude exits cleanly without writing result.json — both paths previously
    // produced false-positives where unrelated PR URLs (e.g. the workspace claim PR
    // echoed via a Read of T<n>.yaml) were captured as the impl PR.

    if (existsSync(resultPath)) {
      let raw: unknown;
      try {
        raw = JSON.parse(readFileSync(resultPath, "utf-8"));
      } catch {
        raw = null;
      }
      if (isValidResult(raw)) {
        let claudeResult = raw as ExecutorResult;
        if (tokenUsage !== undefined && !claudeResult.token_usage) {
          claudeResult.token_usage = { input: tokenUsage.input, output: tokenUsage.output, model: tokenUsage.model };
        }
        if (tokenUsage !== undefined && claudeResult.cost_usd === undefined) {
          claudeResult.cost_usd = tokenUsage.cost_usd;
        }

        // Refuse terminal_status: in_review without a pr_url. Catches the case
        // where the agent skipped pr-create after pr-self-review and exited
        // anyway, so the orchestrator does not advance the task to in_review
        // with no impl PR (or with the workspace claim PR url misclaimed as
        // the impl PR — see enforce-pr-url.ts for context).
        const enforced = enforceInReviewRequiresPrUrl(claudeResult);
        if (enforced.rewritten) {
          emit({
            type: "in_review_refused_no_pr_url",
            task_id: taskId,
            feature_id: featureId,
          });
        }
        claudeResult = enforced.result;

        if (
          budgetTokens !== undefined &&
          tokenUsage !== undefined &&
          tokenUsage.input + tokenUsage.output > budgetTokens
        ) {
          writeResult(resultPath, {
            terminal_status: "blocked",
            blocked_reason: "budget_exceeded",
            token_usage: tokenUsage,
          });
        } else {
          writeResult(resultPath, claudeResult);
        }

        if (logSinkEnabled && workspaceRoot && taskBranch) {
          flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, claudeResult.terminal_status, sshKeyPath, emit);
          logFlushed = true;
        }

        // Return normally — Layer 1 recovery (finally block below) will no-op
        // because a valid result.json now exists.
        return;
      }
    }

    // ── 9. Claude did not write result.json ──────────────────────────────────
    // Budget-exceeded: write blocked immediately (deterministic, no recovery side-effects needed).
    if (
      budgetTokens !== undefined &&
      tokenUsage !== undefined &&
      tokenUsage.input + tokenUsage.output > budgetTokens
    ) {
      writeResult(resultPath, {
        terminal_status: "blocked",
        blocked_reason: "budget_exceeded",
        token_usage: tokenUsage,
      });
      if (logSinkEnabled && workspaceRoot && taskBranch) {
        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, "blocked", sshKeyPath, emit);
        logFlushed = true;
      }
      return;
    }

    // No result.json produced — recovery will write one in the finally block.

  } finally {
    // ── Layer 1: post-hoc recovery ────────────────────────────────────────────
    // Runs regardless of how the spawn ended. No-op when result.json has a
    // valid in_review result (Claude finished cleanly). Otherwise: commits
    // uncommitted work, pushes, opens a draft PR, writes handover.md, and
    // writes a blocked result.json.
    await runRecovery({
      spawnResult,
      taskId,
      featureId,
      taskRepoBranch,
      taskRepoPath: implDir,
      taskRepoUrl,
      githubToken,
      sshKeyPath,
      gitAuthorEmail,
      gitAuthorName,
      resultPath,
      tokenUsage: tokenUsage ? { input: tokenUsage.input, output: tokenUsage.output } : undefined,
      kind: executorKind,
      implPrUrl: implPrUrl || undefined,
    });

    // Flush log after recovery (best-effort, uses result.json to determine outcome).
    // Skip if already flushed in the success or budget-exceeded paths above.
    if (!logFlushed && logSinkEnabled && workspaceRoot && taskBranch) {
      let outcome = "unknown";
      try {
        const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as ExecutorResult;
        outcome = raw.terminal_status;
      } catch { /* ignore */ }
      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult?.stdout ?? "", outcome, sshKeyPath, emit);
    }
  }
}


