import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { setupGlobalSettings } from "./setup-global-settings.js";

vi.mock("node:fs", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:fs")>();
  return {
    ...actual,
    existsSync: vi.fn(),
    mkdirSync: vi.fn(),
    copyFileSync: vi.fn(),
  };
});

vi.mock("node:os", () => ({
  homedir: vi.fn(() => "/home/testuser"),
}));

describe("setupGlobalSettings", () => {
  let emitted: Array<Record<string, unknown>>;
  let emit: (event: Record<string, unknown>) => void;

  beforeEach(() => {
    emitted = [];
    emit = (event) => { emitted.push(event); };
    vi.clearAllMocks();
    vi.mocked(os.homedir).mockReturnValue("/home/testuser");
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("emits claude_settings_missing when template is absent", () => {
    vi.mocked(fs.existsSync).mockReturnValue(false);

    setupGlobalSettings("/workflow", emit);

    expect(emitted).toHaveLength(1);
    expect(emitted[0]?.type).toBe("claude_settings_missing");
    expect((emitted[0] as { src: string })?.src).toBe(
      path.join("/workflow", "templates", "claude-settings.json"),
    );
    expect(fs.copyFileSync).not.toHaveBeenCalled();
  });

  it("does not throw when template is absent", () => {
    vi.mocked(fs.existsSync).mockReturnValue(false);

    expect(() => setupGlobalSettings("/workflow", emit)).not.toThrow();
  });

  it("copies template to ~/.claude/settings.json when template is present", () => {
    vi.mocked(fs.existsSync).mockReturnValue(true);

    setupGlobalSettings("/workflow", emit);

    const expectedSrc = path.join("/workflow", "templates", "claude-settings.json");
    const expectedDest = path.join("/home/testuser", ".claude", "settings.json");
    expect(fs.copyFileSync).toHaveBeenCalledWith(expectedSrc, expectedDest);
  });

  it("creates destination directory before copying", () => {
    vi.mocked(fs.existsSync).mockReturnValue(true);

    setupGlobalSettings("/workflow", emit);

    const expectedDestDir = path.join("/home/testuser", ".claude");
    expect(fs.mkdirSync).toHaveBeenCalledWith(expectedDestDir, { recursive: true });
  });

  it("emits claude_settings_written on success", () => {
    vi.mocked(fs.existsSync).mockReturnValue(true);

    setupGlobalSettings("/workflow", emit);

    expect(emitted).toHaveLength(1);
    expect(emitted[0]?.type).toBe("claude_settings_written");
    expect((emitted[0] as { dest: string })?.dest).toBe(
      path.join("/home/testuser", ".claude", "settings.json"),
    );
  });

  it("uses workflowLocalPath to construct the source path", () => {
    vi.mocked(fs.existsSync).mockReturnValue(false);

    setupGlobalSettings("/custom/workflow/path", emit);

    expect((emitted[0] as { src: string })?.src).toBe(
      path.join("/custom/workflow/path", "templates", "claude-settings.json"),
    );
  });
});

